  it("excludes another tenant's issues from every list query", async () => {
    const northIssue = await insertIssue(north, { title: "North only" });
    await insertIssue(acme, { title: "Acme only" });

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 25,
      cursor: null,
