/**
 * The URL is the single source of truth for the issue list filter: a filtered
 * view has to be shareable and survive a reload, and the server component that
 * renders the page parses the very same query string. These two functions are
 * that codec, kept pure so both sides can use them.
 *
 * The vocabulary is ADR 0009's. Each value is read through the same schema the
 * filter is validated with (`@/schemas/issue`), so a value this codec keeps is
 * one the schema accepts, and it means the same thing in both places.
 *
 * `assignee=none` is the sanctioned spelling of "unassigned" — `undefined`
 * means "don't filter on assignee at all", which is a different query.
 */
import type { ZodType } from "zod";
import {
  assigneeFilterSchema,
  authorFilterSchema,
  dueBeforeSchema,
} from "@/schemas/issue";
import { labelIdSchema, projectIdSchema } from "@/schemas/common";
import {
  expandStatusFilter,
  ISSUE_PRIORITIES,
  isIssueStatusFilterValue,
  ME_TOKEN,
  UNASSIGNED_TOKEN,
  type IssueFilter,
  type IssuePriority,
} from "@/types/issue";

export { ME_TOKEN, UNASSIGNED_TOKEN };

export interface ReadableParams {
  get(name: string): string | null;
}

/** Adapts a Next.js `searchParams` record to the codec's reader; a repeated key keeps its first value. */
export function readableParams(
  search: Readonly<Record<string, string | readonly string[] | undefined>>,
): ReadableParams {
  return {
    get(name) {
      const value = search[name];
      const first = typeof value === "string" ? value : value?.[0];
      return first ?? null;
    },
  };
}

function splitList(raw: string | null): readonly string[] {
  if (raw === null || raw.length === 0) return [];
  return raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

/** `{ value }` when the schema accepts the raw value, `undefined` when it is absent or refused. */
function read<T>(
  schema: ZodType<T>,
  raw: string | null,
): { readonly value: T } | undefined {
  if (raw === null || raw.length === 0) return undefined;
  const parsed = schema.safeParse(raw);
  return parsed.success ? { value: parsed.data } : undefined;
}

/** Keeps each list entry the schema accepts, in order. */
function readEach<T>(
  schema: ZodType<T>,
  values: readonly string[],
): readonly T[] {
  return values.flatMap((value) => {
    const parsed = schema.safeParse(value);
    return parsed.success ? [parsed.data] : [];
  });
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  const statuses = expandStatusFilter(
    splitList(params.get("status")).filter(isIssueStatusFilterValue),
  );
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = readEach(labelIdSchema, splitList(params.get("label")));
  const project = read(projectIdSchema, params.get("project"));
  const assignee = read(assigneeFilterSchema, params.get("assignee"));
  const author = read(authorFilterSchema, params.get("author"));
  const query = params.get("q");
  const dueBefore = read(dueBeforeSchema, params.get("due_before"));
  const archived = params.get("archived");

  const filter: IssueFilter = {
    ...(project !== undefined ? { projectId: project.value } : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(assignee !== undefined ? { assigneeId: assignee.value } : {}),
    ...(author !== undefined ? { authorId: author.value } : {}),
    ...(labelIds.length > 0 ? { labelIds } : {}),
    ...(query !== null && query.length > 0 ? { query } : {}),
    ...(dueBefore !== undefined ? { dueBefore: dueBefore.value } : {}),
    ...(archived === "1" ? { includeArchived: true } : {}),
    ...(archived === "only" ? { archivedOnly: true } : {}),
  };

  return filter;
}

/** Inverse of `parseIssueFilterParams`; omits every empty dimension so the
 *  canonical URL for "no filter" is the bare path. */
export function issueFilterToParams(
  filter: IssueFilter,
): Readonly<Record<string, string>> {
  const params: Record<string, string> = {};
  if (filter.projectId !== undefined) params.project = filter.projectId;
  if (filter.status !== undefined && filter.status.length > 0) {
    params.status = filter.status.join(",");
  }
  if (filter.priority !== undefined && filter.priority.length > 0) {
    params.priority = filter.priority.join(",");
  }
  if (filter.assigneeId !== undefined) {
    params.assignee = filter.assigneeId ?? UNASSIGNED_TOKEN;
  }
  if (filter.authorId !== undefined) params.author = filter.authorId;
  if (filter.labelIds !== undefined && filter.labelIds.length > 0) {
    params.label = filter.labelIds.join(",");
  }
  if (filter.query !== undefined && filter.query.length > 0) {
    params.q = filter.query;
  }
  if (filter.dueBefore !== undefined) params.due_before = filter.dueBefore;
  if (filter.archivedOnly === true) {
    params.archived = "only";
  } else if (filter.includeArchived === true) {
    params.archived = "1";
  }
  return params;
}

/** How many dimensions the user has narrowed on, for the "clear" affordance. */
export function activeFilterCount(filter: IssueFilter): number {
  return Object.keys(issueFilterToParams(filter)).length;
}

export function issueFilterQueryString(filter: IssueFilter): string {
  const search = new URLSearchParams(issueFilterToParams(filter));
  const serialised = search.toString();
  return serialised.length > 0 ? `?${serialised}` : "";
}

