/**
 * Builds the shared predicate list behind `listIssues` and its count. The
 * vocabulary is ADR 0009's: status groups expand here, `assigneeId: null` is
 * "unassigned", labels are all-of, `dueBefore` is an exclusive bound.
 */
function issueFilters(input: ResolvedIssueFilter): readonly SQL[] {
  const archived =
    input.archivedOnly === true
      ? archivedOnlyPredicate(issues.archivedAt)
      : livePredicate(issues.archivedAt, input);

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    archived,
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    input.status === undefined || input.status.length === 0
      ? undefined
      : inArray(issues.status, [...expandStatusFilter(input.status)]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    input.assigneeId === undefined
      ? undefined
      : input.assigneeId === null
        ? isNull(issues.assigneeId)
        : eq(issues.assigneeId, input.assigneeId),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    // Compared as instants, not strings: stored due dates and the bound may
    // carry different offsets or fraction digits. A missing due date is NULL
    // and never matches.
    input.dueBefore === undefined
      ? undefined
      : sql`julianday(${issues.dueAt}) < julianday(${dueBeforeBound(input.dueBefore)})`,
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    labelsAllOf(input),
  );
}

/** An issue matches only when it carries every listed label. */
function labelsAllOf(input: ResolvedIssueFilter): SQL | undefined {
  const labelIds = [...new Set(input.labelIds ?? [])];
  if (labelIds.length === 0) return undefined;

  return inArray(
    issues.id,
    getDb()
      .select({ id: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, input.orgId),
          inArray(issueLabels.labelId, labelIds),
        ),
      )
      .groupBy(issueLabels.issueId)
      .having(sql`count(distinct ${issueLabels.labelId}) = ${labelIds.length}`),
  );
}

