/** `me` in a filter is the acting user, whichever entry point sent it. */
function resolveMe(
  input: IssueFilterInput,
  me: UserId,
): ResolvedIssueFilter {
  const { assigneeId, authorId, ...rest } = input;
  return {
    ...rest,
    ...(assigneeId === undefined
      ? {}
      : { assigneeId: assigneeId === ME_TOKEN ? me : assigneeId }),
    ...(authorId === undefined
      ? {}
      : { authorId: authorId === ME_TOKEN ? me : authorId }),
  };
}

