import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { parseIssueFilterParams } from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
let t: Awaited<ReturnType<typeof createTenant>>;
let L1: string;
let L2: string;
const ids: Record<string, string> = {};

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("scratch-filters");
  L1 = (await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ef4444", description: null })).id;
  L2 = (await labelRepo.insertLabel({ orgId: t.org.id, name: "regression", color: "#00ff00", description: null })).id;

  async function add(key: string, over: Record<string, unknown>) {
    const number = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
    const base = issueInput(t.org.id, t.project.id, { title: key });
    const row = await issueRepo.insertIssue({ ...base, ...over } as never, t.userIds.owner, number);
    ids[key] = row.id;
  }
  // A: open, unassigned, both labels, due late on 9 Oct UTC
  await add("A", { status: "backlog", assigneeId: null, labelIds: [L1, L2], dueAt: "2026-10-09T23:30:00.000Z" });
  // B: closed, assigned, only L1, due 00:00 on 10 Oct
  await add("B", { status: "done", assigneeId: t.userIds.member, labelIds: [L1], dueAt: "2026-10-10T00:00:00.000Z" });
  // C: open, unassigned, both labels, no due date; archived below
  await add("C", { status: "todo", assigneeId: null, labelIds: [L1, L2], dueAt: null });
  // D: in progress, assigned, no labels, due 8 Oct with a Z-suffixed no-ms form
  await add("D", { status: "in_progress", assigneeId: t.userIds.member, labelIds: [], dueAt: "2026-10-08T10:00:00Z" });
  await issueRepo.archiveIssue(t.org.id, ids.C as never);
});

afterAll(() => cleanup());

async function list(extra: Record<string, unknown>) {
  const page = await issueRepo.listIssues({ orgId: t.org.id, limit: 100, cursor: null, ...extra } as never);
  return { keys: Object.entries(ids).filter(([, id]) => page.items.some((i) => i.id === id)).map(([k]) => k).sort(), total: page.total, n: page.items.length };
}

describe("scratch: issue filters", () => {
  it("unassigned means assignee IS NULL", async () => {
    expect((await list({ assigneeId: null })).keys).toEqual(["A"]);
  });
  it("labels are all-of, and total agrees", async () => {
    const r = await list({ labelIds: [L1, L2] });
    expect(r.keys).toEqual(["A"]);
    expect(r.total).toBe(r.n);
  });
  it("due_before date includes the whole day", async () => {
    expect((await list({ dueBefore: "2026-10-09" })).keys).toEqual(["A", "D"]);
  });
  it("due_before timestamp is strict", async () => {
    expect((await list({ dueBefore: "2026-10-10T00:00:00.000Z" })).keys).toEqual(["A", "D"]);
    expect((await list({ dueBefore: "2026-10-10T00:00:00.001Z" })).keys).toEqual(["A", "B", "D"]);
  });
  it("status groups expand", async () => {
    expect((await list({ status: ["open"] })).keys).toEqual(["A", "D"]);
    expect((await list({ status: ["closed"] })).keys).toEqual(["B"]);
  });
  it("archived=only lists archived rows alone; default hides them", async () => {
    expect((await list({ archivedOnly: true })).keys).toEqual(["C"]);
    expect((await list({})).keys).toEqual(["A", "B", "D"]);
    expect((await list({ includeArchived: true })).keys).toEqual(["A", "B", "C", "D"]);
  });
  it("codec and schema agree on the vocabulary", () => {
    const f = parseIssueFilterParams(new URLSearchParams("status=open,nonsense&archived=only&due_before=2026-10-09&assignee=me&label=x"));
    expect(f.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    expect(f.archivedOnly).toBe(true);
    expect(f.dueBefore).toBe("2026-10-09");
    expect(f.assigneeId).toBe("me");
    const parsed = issueFilterSchema.safeParse({ orgId: t.org.id, status: ["open"], dueBefore: "2026-10-09", assigneeId: "me", archivedOnly: true });
    expect(parsed.success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["bogus"] }).success).toBe(false);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "10/10/2026" }).success).toBe(false);
    expect(parseIssueFilterParams(new URLSearchParams("due_before=10/10/2026")).dueBefore).toBeUndefined();
  });
});

